// Consume one routed macro-set (first set in this gate). Binary triples to stdout.
#include <algorithm>
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <numeric>
#include <queue>
#include <string_view>
#include <vector>
#include <fcntl.h>
#include <sys/mman.h>
#include <unistd.h>
using namespace std;namespace fs=std::filesystem;using U=uint32_t;using Q=uint64_t;
struct Mass{Q d,b,r;};struct Rec{U id,off,tag,pred;};struct Item{U ptr,req,off,tag,pred;};struct Request{U id,lo,hi;};struct Pair{U pos,r;};struct Occ{Pair pair;U pred;};Q reads(){ifstream f("/proc/self/io");string k;Q v;while(f>>k>>v)if(k=="read_bytes:")return v;abort();}
template<class T>const T* mapping(fs::path p){int fd=open(p.c_str(),O_RDONLY);assert(fd>=0);auto sz=fs::file_size(p);auto a=(const T*)mmap(nullptr,sz,PROT_READ,MAP_PRIVATE,fd,0);close(fd);assert(a!=MAP_FAILED);assert(!madvise((void*)a,sz,MADV_RANDOM));return a;}
U lcp(string_view a,string_view b){U h=0;while(h<a.size()&&h<b.size()&&a[h]==b[h])++h;return h;}
int main(int ac,char**av){assert(ac==6);fs::path d=av[1],spill=av[2],plan=av[3];U limit=stoul(av[4]);Q n=stoull(av[5]);assert(n<=1010000000);ifstream pf(plan,ios::binary);U count;assert(pf.read((char*)&count,4)&&limit<=count);auto loc=mapping<U>(d/"loc.u32");auto pairs=mapping<Pair>(d/"pos-next.u32x2");auto pred=mapping<unsigned char>(d/"pred.u8");U k=fs::file_size(d/"loc.u32")/4-1,m=fs::file_size(d/"aligned.u32")/4;assert(loc[k]==m);const U B=64,nb=(m+B-1)/B;vector<U>tree(2*nb,UINT32_MAX);ifstream af(d/"aligned.u32",ios::binary);for(U i=0;i<m;i++){U x;assert(af.read((char*)&x,4));tree[nb+i/B]=min(tree[nb+i/B],x);}for(U i=nb-1;i;i--)tree[i]=min(tree[2*i],tree[2*i+1]);auto al=mapping<U>(d/"aligned.u32");auto rmq=[&](U a,U b){assert(a<b&&b<=m);U h=UINT32_MAX;while(a<b&&a%B)h=min(h,al[a++]);while(a<b&&b%B)h=min(h,al[--b]);if(a<b){a=a/B+nb;b=b/B+nb;while(a<b){if(a&1)h=min(h,tree[a++]);if(b&1)h=min(h,tree[--b]);a/=2;b/=2;}}return h;};auto guard=[&]{if(reads()>12*n){fprintf(stderr,"STOP read guard\n");exit(75);}};auto emit=[](U p,U h,U b){U row[]={p,h,b};assert(fwrite(row,4,3,stdout)==3);};ifstream cf(d/"corpus",ios::binary);cf.seekg(n-1);int tail=cf.get();assert(tail>=0);emit(n,0,tail);Q rows=1;string boundary;
 for(U w=0;w<limit;w++){Mass mass;U tag;assert(pf.read((char*)&mass,24)&&pf.read((char*)&tag,4));pf.seekg(tag&0x7fffffffu,ios::cur);assert(mass.d<=1100000&&mass.b<=64u<<20&&mass.r<=2000000);vector<char>arena(mass.b);vector<Item>a;a.reserve(mass.d);vector<Request>rq;ifstream f(spill/to_string(w),ios::binary);U used=0;for(Q i=0;i<mass.d;i++){Rec x;assert(f.read((char*)&x,16)&&x.id<k&&x.pred<256);U len=x.tag&0x7fffffff;assert(len&&used+Q(len)<=arena.size()&&f.read(arena.data()+used,len));if(rq.empty()||rq.back().id!=x.id)rq.push_back({x.id,0,0});a.push_back({used,(U)rq.size()-1,x.off,x.tag,x.pred});used+=len;}assert(f.peek()==EOF&&used==mass.b);auto key=[&](Item x){return make_pair(string_view(arena.data()+x.ptr,x.tag&0x7fffffffu),bool(x.tag>>31));};sort(a.begin(),a.end(),[&](Item x,Item y){return key(x)<key(y);});vector<U>order(rq.size());iota(order.begin(),order.end(),0);sort(order.begin(),order.end(),[&](U i,U j){return rq[i].id<rq[j].id;});vector<Occ>occ;occ.reserve(mass.r);for(U ix:order){auto&r=rq[ix];U end=loc[r.id+1];r.lo=occ.size();for(U i=loc[r.id];i<end;i++){assert(occ.size()<mass.r);occ.push_back({pairs[i],pred[i]});}r.hi=occ.size();assert(r.hi>r.lo);}guard();Q begin=rows;using Node=tuple<U,U,U>;for(U i=0;i<a.size();){auto v=key(a[i]);U end=i+1;while(end<a.size()&&key(a[end])==v)++end;U h=lcp(i?key(a[i-1]).first:string_view(boundary),v.first);priority_queue<Node,vector<Node>,greater<Node>>q;for(U j=i;j<end;j++){U z=rq[a[j].req].lo;q.emplace(occ[z].pair.r,z,j);}bool first=true;U prev=0;while(!q.empty()){auto[r,z,j]=q.top();q.pop();if(!first){assert(prev&&prev<r&&v.first.size()+v.second>=8);h=v.first.size()+v.second-8+rmq(prev,r);}U p=occ[z].pair.pos+a[j].off;assert(p<n);emit(p,h,!p?256:(a[j].off?a[j].pred:occ[z].pred));first=false;prev=r;++rows;if(++z<rq[a[j].req].hi)q.emplace(occ[z].pair.r,z,j);}i=end;}assert(rows-begin==mass.r);if(!a.empty())boundary=key(a.back()).first;guard();fprintf(stderr,"WINDOW index=%u cumulative_rows=%llu reads=%llu\n",w,(unsigned long long)rows,(unsigned long long)reads());}assert(fflush(stdout)==0);}
